import{_ as a,C as n,o as s,c as o,E as i,a2 as r}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"Weekly 009 — Completion Must Be Typed: One Green Check Cannot Close the Whole System","description":"","frontmatter":{"title":"Weekly 009 — Completion Must Be Typed: One Green Check Cannot Close the Whole System","date":"2026-09-13","column":"digital-employee","category":"weekly","article_type":"research-brief","edition":"research-center","research_question":"When an agent system reports completed, recovered, verified, or audited, how do we identify which uncertainty was actually closed and which state must remain independently open?","summary":"Fourteen published Daily Research notes from September 7 through 13 repeatedly show that a local terminal state cannot be promoted into a global terminal state. This brief proposes Typed Closure: State, Authority, Effect, and Coverage need separate closure evidence, while Unknown must remain a valid durable state.","sources":["2026-09-07 through 2026-09-13 Daily Runtime V5 evidence-validated publications","research/intelligence/p2-runs/2026/09/2026-09-13-p2-special.json"],"evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"cover":"/assets/covers/weekly-009-typed-closure-cover-v2.webp"},"headers":[],"relativePath":"en/research/weekly/weekly-009.md","filePath":"en/research/weekly/weekly-009.md","lastUpdated":1789371022000}'),l={name:"en/research/weekly/weekly-009.md"};function c(d,e,p,u,h,m){const t=n("ArticleCover");return s(),o("div",null,[i(t,{image:"/assets/covers/weekly-009-typed-closure-cover-v2.webp",kicker:"Weekly Research · 009",title:"Completion Must Be Typed: One Green Check Cannot Close the Whole System",summary:"State, authority, external effects, and coverage each need their own terminal evidence.",version:"W009",status:"Published 2026-09-13",languageHref:"/zh/research/weekly/weekly-009",languageLabel:"中文"}),e[0]||(e[0]=r(`<h1 id="weekly-009-—-completion-must-be-typed-one-green-check-cannot-close-the-whole-system" tabindex="-1">Weekly 009 — Completion Must Be Typed: One Green Check Cannot Close the Whole System <a class="header-anchor" href="#weekly-009-—-completion-must-be-typed-one-green-check-cannot-close-the-whole-system" aria-label="Permalink to &quot;Weekly 009 — Completion Must Be Typed: One Green Check Cannot Close the Whole System&quot;">​</a></h1><p>An agent has been restored to an earlier checkpoint. Is recovery complete? An audit reached its terminal state. Is coverage sufficient? A report passed generation and review checks. Has its conclusion been independently challenged? A tool call returned successfully. Has its external effect actually been established?</p><p>This week&#39;s Daily Research approached these questions from very different systems and repeatedly reached the same answer: <strong>the most visible green state is not enough.</strong></p><p>From September 7 through 13, the Research Center published fourteen Daily Research notes covering multi-agent governance, memory migration, team coordination, cross-boundary side effects, tool execution evidence, independent review, procedures and authority, durable state, checkpoint recovery, and large-scale auditing. They are not rewrites of one topic. Yet they expose one recurring structural failure:</p><blockquote><p><strong>A system closes one kind of uncertainty and silently treats every related uncertainty as closed.</strong></p></blockquote><p>Weekly 008 argued that authority is a relation rather than an object attribute. This week pushes the distinction further. <strong>Completion itself should not be compressed into an untyped Boolean.</strong> A reliable runtime needs to know which fact has reached closure and which fact remains unknown.</p><h2 id="evidence-window-seven-dates-six-published-days-fourteen-research-notes" tabindex="-1">Evidence window: seven dates, six published days, fourteen research notes <a class="header-anchor" href="#evidence-window-seven-dates-six-published-days-fourteen-research-notes" aria-label="Permalink to &quot;Evidence window: seven dates, six published days, fourteen research notes&quot;">​</a></h2><p>This synthesis checked Daily Runtime evidence from <strong>September 7 through September 13, 2026</strong>. Publication has durable <code>Completed</code> results for September 7, 8, 9, 10, 12, and 13, producing <strong>14</strong> Research Center notes. On September 11, Discovery, Queue, Reading, Analysis, and Production are complete, but Publication remains <code>Running</code> in the current authoritative Runtime record. No September 11 unpublished candidate is therefore treated as published evidence in this brief.</p><table tabindex="0"><thead><tr><th>Date</th><th>Published research</th><th>Reusable boundary</th></tr></thead><tbody><tr><td>9/7</td><td>Local Safety Does Not Close the Path; Visibility Is Not Enforcement; Project Truth Survives Context</td><td>Local safety, visibility, and context continuity cannot substitute for an end-to-end execution closure</td></tr><tr><td>9/8</td><td>Memory Must Be Readmitted; Role Match Is Not Team Fit; One Effect Across Surfaces</td><td>Stored data, role matching, and interface consistency each require separate semantic, coordination, or effect evidence</td></tr><tr><td>9/9</td><td>Tool Edge Needs Execution Evidence; Finished Report Needs Challenge Evidence</td><td>A tool boundary needs occurrence evidence; report completion does not establish challenge completion</td></tr><tr><td>9/10</td><td>Second Model Is Not Independent Control; Proposed Procedure Is Not Active Authority</td><td>Another model call is not automatically independent review; a procedure&#39;s existence is not active authority</td></tr><tr><td>9/11</td><td>Not counted as published evidence</td><td>Publication is not closed in the authoritative Runtime record</td></tr><tr><td>9/12</td><td>Evidence Complete Is Not Execution Authority; Retained State Needs Current Authority</td><td>Complete evidence and retained state still do not substitute for current execution admission</td></tr><tr><td>9/13</td><td>State Rewound, Effect Did Not; Audit Completion Is Not Coverage Assurance</td><td>Local rollback does not reverse remote effects; audit termination does not prove adequate coverage</td></tr></tbody></table><p>The September 11 gap is itself consistent with the thesis: the passage of calendar time does not authorize us to rewrite an unfinished Publication state into a completed one. Evidence windows have boundaries too.</p><h2 id="what-exactly-did-completed-close" tabindex="-1">What exactly did <code>Completed</code> close? <a class="header-anchor" href="#what-exactly-did-completed-close" aria-label="Permalink to &quot;What exactly did \`Completed\` close?&quot;">​</a></h2><p>Traditional software often compresses a process into a few terminal states such as <code>success</code>, <code>failed</code>, or <code>done</code>. Inside a deterministic and closed boundary, that can be sufficient because the program knows what it observed and where its effects live.</p><p>Agent systems routinely cross model context, filesystems, remote APIs, approval chains, memory stores, audit corpora, and human responsibility boundaries. A module reaching a terminal state can only establish closure for the class of fact that module is able and authorized to observe.</p><p>This week&#39;s research can be organized into four frequently confused closure types:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State Closure</span></span>
<span class="line"><span>Authority Closure</span></span>
<span class="line"><span>Effect Closure</span></span>
<span class="line"><span>Coverage Closure</span></span></code></pre></div><p>They interact, but none is a substitute for another.</p><h2 id="state-closure-stable-state-does-not-mean-admitted-state" tabindex="-1">State Closure: stable state does not mean admitted state <a class="header-anchor" href="#state-closure-stable-state-does-not-mean-admitted-state" aria-label="Permalink to &quot;State Closure: stable state does not mean admitted state&quot;">​</a></h2><p>September 8&#39;s memory-migration research provides a clean counterexample. Old memory can remain byte-complete, parseable, and even dimensionally compatible after a model, writer, reader, or embedding change, while the semantic contract has changed.</p><p>&quot;The data still exists&quot; is therefore a State Closure fact. To make that memory authoritative in a new runtime, the system still needs semantic-compatibility evidence, a recovery path, and an activation decision.</p><p>The September 12 retained-state study generalizes the boundary: <strong>persistence establishes continuity, not current authority.</strong> State may survive a restart, but a change in policy, target, principal, or occurrence can require fresh admission before the retained state may drive another action.</p><p>A runtime should therefore resist collapsing everything into:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state = restored</span></span></code></pre></div><p>It may need to preserve:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state_integrity = closed</span></span>
<span class="line"><span>semantic_compatibility = ?</span></span>
<span class="line"><span>authority = ?</span></span></code></pre></div><p>Those question marks are not software defects. They are facts the system has not yet obtained.</p><h2 id="authority-closure-a-procedure-an-approving-model-or-a-complete-evidence-bundle-is-not-active-permission" tabindex="-1">Authority Closure: a procedure, an approving model, or a complete evidence bundle is not active permission <a class="header-anchor" href="#authority-closure-a-procedure-an-approving-model-or-a-complete-evidence-bundle-is-not-active-permission" aria-label="Permalink to &quot;Authority Closure: a procedure, an approving model, or a complete evidence bundle is not active permission&quot;">​</a></h2><p>Two September 10 studies show the distinction from different directions.</p><p>The first asks why a second model is not automatically an independent control. If it consumes the same narrative, shares the same information path, or lacks an independent responsibility boundary, an additional model call produces another judgment, not necessarily independent supervision.</p><p>The second asks why a proposed procedure is not active authority. A policy or procedure can be complete on paper, while activation still depends on who may adopt it, what targets it governs, when it takes effect, and which policy epoch recognizes it.</p><p>September 12&#39;s Evidence Complete Is Not Execution Authority adds a third form: even a complete evidence bundle does not let a system jump from &quot;the evidence is sufficient&quot; to &quot;the action may execute.&quot; Evidence supports a decision; it is not the decision itself.</p><p>Authority Closure answers a deliberately narrow question:</p><blockquote><p>May this principal, under the current policy and occurrence, execute this action against this target now?</p></blockquote><p>That is not the same state as report completion, procedure existence, or model agreement.</p><h2 id="effect-closure-internal-state-can-go-backward-while-the-world-does-not" tabindex="-1">Effect Closure: internal state can go backward while the world does not <a class="header-anchor" href="#effect-closure-internal-state-can-go-backward-while-the-world-does-not" aria-label="Permalink to &quot;Effect Closure: internal state can go backward while the world does not&quot;">​</a></h2><p>September 13&#39;s State Rewound, Effect Did Not exposes one of the most dangerous closure errors.</p><p>Aligned checkpoints can restore model context and a controlled workspace to the same historical point. That is valuable recovery. But a network request, remote database write, message, payment, or consumed resource may already have escaped the checkpoint boundary.</p><p>The system can therefore look internally clean while being externally inconsistent:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>local_state = before_call</span></span>
<span class="line"><span>remote_effect = already_happened</span></span></code></pre></div><p>If the runtime observes only State Closure, the next call may be mistaken for a first execution. Safe recovery requires separate Effect Closure evidence: the original effect is proved absent, proved present and acceptable, verified as compensated, irreversible, or still unknown.</p><p>This suggests a separate effect ledger carrying occurrence identity, target, request identity, idempotency key, remote receipt, compensation identity, and a current authoritative read. <strong>A missing response is not proof that the effect did not happen; rolling back a local file is not proof that a remote fact was reversed.</strong></p><h2 id="coverage-closure-the-audit-finished-but-did-it-look-everywhere-it-claimed-to-cover" tabindex="-1">Coverage Closure: the audit finished, but did it look everywhere it claimed to cover? <a class="header-anchor" href="#coverage-closure-the-audit-finished-but-did-it-look-everywhere-it-claimed-to-cover" aria-label="Permalink to &quot;Coverage Closure: the audit finished, but did it look everywhere it claimed to cover?&quot;">​</a></h2><p>Audit Completion Is Not Coverage Assurance studies a different system with the same structure.</p><p>An audit may terminate without runtime errors and still miss relevant evidence that never entered its search scope. <code>Completed</code> proves completion of the configured process; it cannot prove that the evidence universe was adequately covered.</p><p>Coverage Closure needs durable facts of its own: source and time boundaries, funnel identity, stage counts, known-positive recall, rejected-sample evidence, unreadable records, semantic-review identity, and what an independent reviewer actually completed.</p><p>This also explains September 9&#39;s Finished Report Needs Challenge Evidence. A report can close its writing state while the status of adversarial testing, alternative explanations, and independent challenge remains separate.</p><p>A more truthful audit result may be:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>execution = completed</span></span>
<span class="line"><span>coverage = bounded</span></span>
<span class="line"><span>residual_unknown = explicit</span></span></code></pre></div><p>rather than an unsupported <code>coverage = complete</code>.</p><h2 id="why-one-global-status-creates-semantic-escalation" tabindex="-1">Why one global status creates semantic escalation <a class="header-anchor" href="#why-one-global-status-creates-semantic-escalation" aria-label="Permalink to &quot;Why one global status creates semantic escalation&quot;">​</a></h2><p>Compressing these closures into <code>done=true</code> creates three recurring errors.</p><p>First is <strong>scope expansion</strong>: evidence about a local boundary is silently promoted into evidence about the whole system. A local safety check passes, therefore the entire path is called safe.</p><p>Second is <strong>responsibility drift</strong>: a component that merely records state starts making decisions that belong to an authority owner, effect reconciler, or audit reviewer.</p><p>Third is <strong>erasure of unknowns</strong>: the runtime loses the ability to distinguish &quot;proved absent&quot; from &quot;not observed,&quot; or &quot;effect did not happen&quot; from &quot;effect status unknown.&quot;</p><p>Agent runtimes need fewer ambiguous green icons and more precise meanings for each one.</p><h2 id="a-practical-typed-closure-envelope" tabindex="-1">A practical Typed Closure Envelope <a class="header-anchor" href="#a-practical-typed-closure-envelope" aria-label="Permalink to &quot;A practical Typed Closure Envelope&quot;">​</a></h2><p>The week&#39;s evidence supports a simple engineering abstraction: preserve a <strong>Typed Closure Envelope</strong> for consequential work instead of a single terminal bit.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypedClosure {</span></span>
<span class="line"><span>  state:     Open | Closed | Unknown</span></span>
<span class="line"><span>  authority: Open | Closed | Unknown</span></span>
<span class="line"><span>  effect:    Open | Closed | Unknown</span></span>
<span class="line"><span>  coverage:  Open | Closed | Bounded | Unknown</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  evidence_refs[]</span></span>
<span class="line"><span>  policy_epoch</span></span>
<span class="line"><span>  occurrence_id</span></span>
<span class="line"><span>  updated_at</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The same mechanism should not close all four dimensions. Each dimension should be closed by a mechanism that can observe the relevant facts and carries responsibility for that boundary:</p><ul><li>State is supported by persistence and consistency evidence.</li><li>Authority is decided by the current authorization boundary and accountable authority holder.</li><li>Effect is established from authoritative target evidence or governed compensation.</li><li>Coverage is supported by scope, funnel, sampling, known-positive, and independent-review evidence.</li></ul><p>Not every task needs all four dimensions. The principle is narrower: <strong>one closure type must not be silently reinterpreted as another.</strong></p><h2 id="unknown-must-be-allowed-to-persist" tabindex="-1">Unknown must be allowed to persist <a class="header-anchor" href="#unknown-must-be-allowed-to-persist" aria-label="Permalink to &quot;Unknown must be allowed to persist&quot;">​</a></h2><p>Agent systems often treat Unknown as an exception that should quickly be collapsed into True or False. This week&#39;s recovery and audit evidence shows why that can be unsafe.</p><p>After an external call times out, the side effect may be unknown. After an audit funnel ends, residual relevant records may be unknown. After a model migration, semantic equivalence of old memory may be unknown.</p><p>Without enough evidence, these states should remain Unknown. Unknown can trigger more evidence gathering, human adjudication, a reduced operating scope, or fail-closed behavior. It should not be guessed away merely because an API wants a Boolean.</p><p><strong>Preserving Unknown is itself a governance capability.</strong></p><h2 id="p2-no-manufactured-special-study-this-week" tabindex="-1">P2: no manufactured special study this week <a class="header-anchor" href="#p2-no-manufactured-special-study-this-week" aria-label="Permalink to &quot;P2: no manufactured special study this week&quot;">​</a></h2><p>Four <code>biweekly-or-release</code> P2 objects were due this week: agent-audit, Aegis, agent-style, and cs-paper-checklist. Their main/release identities are unchanged from the September 6 checkpoints, so all four close as <code>No Material Change</code>. The two monthly objects completed their September full reviews on September 6 and are not due again this week.</p><p>Coverage is <strong>4/4 due objects resolved, zero objects at or above the trigger threshold of 5, and zero full Special Studies started.</strong> This is not missing output; it is the checkpoint mechanism doing its job. Without new primary-source change, the system does not manufacture repeat research.</p><h2 id="the-next-question-is-not-more-statuses-it-is-transition-contracts" tabindex="-1">The next question is not more statuses; it is transition contracts <a class="header-anchor" href="#the-next-question-is-not-more-statuses-it-is-transition-contracts" aria-label="Permalink to &quot;The next question is not more statuses; it is transition contracts&quot;">​</a></h2><p>Typed Closure is an engineering abstraction synthesized from this week&#39;s evidence, not a generally validated standard. The next useful tests concern transitions between the states:</p><ul><li>Which changes must reopen Authority after State has closed?</li><li>How long may Effect remain Unknown before a human decision is required instead of another automated retry?</li><li>At what risk level is Bounded Coverage sufficient for a business decision?</li><li>Does adding a new source automatically invalidate an older Coverage closure?</li><li>What information separation and responsibility separation make a second review genuinely independent?</li><li>When multiple agents close different dimensions, who proves that they refer to the same occurrence?</li></ul><p>Without transition contracts, Typed Closure would eventually become another collection of labels.</p><p>The week&#39;s most useful conclusion is therefore not that systems need more status fields. It is more precise:</p><blockquote><p><strong>Completion is meaningful only when the system says what was completed.</strong></p></blockquote><p>A system may have restored state without restoring authority. It may have completed an audit without completing coverage assurance. It may have completed a report without completing independent challenge. It may have returned to an old checkpoint without reversing an external effect.</p><p>Separating those facts prevents one local green check from pretending that the whole world is closed.</p><h2 id="evidence-entry-points" tabindex="-1">Evidence entry points <a class="header-anchor" href="#evidence-entry-points" aria-label="Permalink to &quot;Evidence entry points&quot;">​</a></h2><ul><li><a href="/joinwell52/en/industry/2026-09-07-visibility-is-not-enforcement">9/7: Visibility Is Not Enforcement</a></li><li><a href="/joinwell52/en/digital-employee/2026-09-08-memory-must-be-readmitted">9/8: Memory Must Be Readmitted</a></li><li><a href="/joinwell52/en/digital-employee/2026-09-09-tool-edge-needs-execution-evidence">9/9: Tool Edge Needs Execution Evidence</a></li><li><a href="/joinwell52/en/digital-employee/2026-09-10-second-model-not-independent-control">9/10: Second Model Is Not Independent Control</a></li><li><a href="/joinwell52/en/digital-employee/2026-09-12-evidence-complete-not-execution-authority">9/12: Evidence Complete Is Not Execution Authority</a></li><li><a href="/joinwell52/en/digital-employee/2026-09-13-state-rewound-effect-did-not">9/13: State Rewound, Effect Did Not</a></li><li><a href="/joinwell52/en/industry/2026-09-13-audit-completion-not-coverage-assurance">9/13: Audit Completion Is Not Coverage Assurance</a></li><li>P2 check record: <code>research/intelligence/p2-runs/2026/09/2026-09-13-p2-special.json</code></li></ul>`,78))])}const f=a(l,[["render",c]]);export{b as __pageData,f as default};
